SELECT "deal_name" AS "deal_name", "deal_id" AS "deal_id", "product" AS "product", "pricing_ts" AS "pricing_date", "deal_size" AS "deal_size", "offering_type" AS "offering_type", "product_class" AS "product_class", "order_demand_qty" AS "order_demand_qty", "order_allocation" AS "order_allocation", "demand_unit" AS "demand_unit", "currency" AS "currency", "equity_type" AS "equity_type", COUNT("order_id") AS "row_count" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" IN (__P_f0_0__, __P_f0_1__) AND UPPER("investor_name") LIKE UPPER(__P_f1__) AND "pricing_ts" >= __P_f2__ GROUP BY "deal_name", "deal_id", "product", "pricing_ts", "deal_size", "offering_type", "product_class", "order_demand_qty", "order_allocation", "demand_unit", "currency", "equity_type" ORDER BY "pricing_date" DESC, "deal_name" ASC LIMIT 50
